script:
(function () {
  'use strict';
  // 401(k) with profit sharing. Each year you defer contrib% of pay; the employer adds a match
  // (match% of your deferral up to matchCap% of pay) and, in the years it pays one, a discretionary
  // profit-sharing contribution of share% of pay. Deposits go in monthly and compound monthly at
  // (1 + annual return)^(1/12) - 1, the same convention as 401k-calculator.
  // With limits on: pay counted for the plan is capped at the 401(a)(17) limit; deferrals are capped at
  // the 402(g) limit plus the age catch-up; annual additions (deferrals excluding catch-up + match +
  // profit sharing) are capped at the lesser of the 415(c) dollar limit and 100% of pay. When the cap
  // binds, profit sharing is cut first, then the match.
  // "Profit sharing is paid" spreads paid years evenly: year y (0-based) is paid when
  // ceil((y + 1) x f) > ceil(y x f), so 3 in 4 = paid, paid, paid, skipped; every other = paid, skipped.
  // Checked in Node (scratchpad solo401k/tests/ps.test.js, whole script on a fake DOM): no-raise
  // $60,000 pay, 0 balance, 10% total for 30 years at 7% -> $500/month annuity = $584,726 (matches
  // 401k-calculator); $75,000 at 8% with 50% match up to 6% and 5% profit sharing -> $6,000 + $2,250 +
  // $3,750; $300,000 pay at 10% + 100% match to 6% + 15% profit sharing, age 40 -> deferral $24,500,
  // match $18,000, profit sharing cut from $45,000 to $29,500 (total $72,000); $500,000 pay -> pay
  // capped at $360,000; age 61 -> $11,250 catch-up outside the $72,000; 3-in-4 pattern pays 3 of 4 years.
  // ---- 2026 IRS limits (IRS Notice 2025-67, tax year 2026) ----------------------------------------
  var LIMITS = {
    year: 2026,
    deferral: 24500,        // 402(g) elective deferral limit (pre-tax + Roth)
    catchUp50: 8000,        // 414(v) catch-up, age 50 or older by year-end
    catchUp60to63: 11250,   // SECURE 2.0 higher catch-up, ages 60-63 (replaces the age-50 amount)
    annualAdditions: 72000, // 415(c) limit: deferrals + match + profit sharing (catch-up excluded)
    compensation: 360000    // 401(a)(17) maximum pay counted by the plan
  };
  // -------------------------------------------------------------------------------------------------

  function catchUpFor(age) {
    if (age >= 60 && age <= 63) return LIMITS.catchUp60to63;
    if (age >= 50) return LIMITS.catchUp50;
    return 0;
  }
  function sharePaid(freq, y) { return Math.ceil((y + 1) * freq - 1e-9) > Math.ceil(y * freq - 1e-9); }

  // p: age, retireAge, salary, raise, balance, contrib, match, matchCap, share, freq, rate, inflation
  //    (decimals), applyLimits.
  function project(p) {
    var years = p.retireAge - p.age, mRate = Math.pow(1 + p.rate, 1 / 12) - 1;
    var bal = p.balance, salary = p.salary, tot = { you: 0, match: 0, share: 0 }, rows = [], capped = false;
    for (var y = 0; y < years; y++) {
      var ageNow = p.age + y;
      var pay = p.applyLimits ? Math.min(salary, LIMITS.compensation) : salary;
      var you = pay * p.contrib, catchUp = 0, regular = you;
      if (p.applyLimits) {
        var maxYou = LIMITS.deferral + catchUpFor(ageNow);
        if (you > maxYou) { you = maxYou; capped = true; }
        regular = Math.min(you, LIMITS.deferral);
        catchUp = you - regular;
      }
      var effPct = pay > 0 ? you / pay : 0;
      var match = pay * p.match * Math.min(effPct, p.matchCap);
      var share = sharePaid(p.freq, y) ? pay * p.share : 0;
      var room = Infinity;
      if (p.applyLimits) {
        var cap = Math.min(LIMITS.annualAdditions, pay);
        if (regular > cap) { regular = cap; you = regular + catchUp; capped = true; }
        if (regular + match + share > cap) {
          capped = true;
          share = Math.max(0, cap - regular - match);
          match = Math.min(match, cap - regular);
        }
        room = Math.max(0, cap - regular - match - share);
      }
      var dep = (you + match + share) / 12;
      for (var m = 0; m < 12; m++) bal = bal * (1 + mRate) + dep;
      tot.you += you; tot.match += match; tot.share += share;
      rows.push({ age: ageNow, salary: salary, you: you, regular: regular, catchUp: catchUp, match: match,
                  share: share, room: room, balance: bal });
      salary = salary * (1 + p.raise);
    }
    return { balance: bal, real: bal / Math.pow(1 + p.inflation, years), you: tot.you, match: tot.match,
             share: tot.share, growth: bal - p.balance - tot.you - tot.match - tot.share, rows: rows, capped: capped };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }

  function update() {
    var p = { age: num('psAge'), retireAge: num('psRetireAge'), salary: num('psSalary'), raise: num('psRaise'),
              balance: num('psBalance'), contrib: num('psContrib'), match: num('psMatch'), matchCap: num('psMatchCap'),
              share: num('psShare'), freq: parseFloat(document.getElementById('psFreq').value), rate: num('psRate'),
              inflation: num('psInflation'), applyLimits: document.getElementById('psLimits').checked };
    var error = document.getElementById('psError');
    var bad = [p.age, p.retireAge, p.salary, p.raise, p.balance, p.contrib, p.match, p.matchCap, p.share, p.freq,
               p.rate, p.inflation].some(isNaN) ||
              p.age !== Math.round(p.age) || p.retireAge !== Math.round(p.retireAge) || p.age < 16 || p.age > 99 ||
              p.retireAge <= p.age || p.retireAge > 100 || p.salary < 0 || p.balance < 0 || p.raise < 0 || p.raise > 20 ||
              p.contrib < 0 || p.contrib > 100 || p.match < 0 || p.match > 200 || p.matchCap < 0 || p.matchCap > 100 ||
              p.share < 0 || p.share > 100 || p.rate < 0 || p.rate > 30 || p.inflation < 0 || p.inflation > 20;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter whole-number ages from 16 to 99 with retirement above your age (up to 100), non-negative ' +
                          'amounts, percentages from 0 to 100 (match up to 200%), a return up to 30% and inflation up to 20%.';
      return;
    }
    ['raise', 'contrib', 'match', 'matchCap', 'share', 'rate', 'inflation'].forEach(function (k) { p[k] = p[k] / 100; });
    var r = project(p);
    var noShare = project(Object.assign({}, p, { share: 0 }));
    set('psRetireLabel', 'Balance at age ' + p.retireAge);
    set('psFuture', fmt(r.balance)); set('psReal', fmt(r.real)); set('psYou', fmt(r.you));
    set('psMatchTotal', fmt(r.match)); set('psShareTotal', fmt(r.share)); set('psGrowth', fmt(r.growth));
    var worth = r.balance - noShare.balance;
    set('psShareWorth', worth > 0.5
      ? 'Profit sharing and the growth on it make up ' + fmt(worth) + ' of your balance at ' + p.retireAge +
        ' (' + Math.round(worth / r.balance * 100) + '%). Without it you would have ' + fmt(noShare.balance) + '.'
      : 'No profit-sharing contributions are included in this projection.');
    var capEl = document.getElementById('psCapped');
    capEl.hidden = !r.capped;
    if (r.capped) set('psCapped', 'In some years your deferral, the match or the profit-sharing contribution is reduced to stay ' +
        'within the ' + LIMITS.year + ' IRS limits. Profit sharing is cut first when the total limit is reached.');
    var f = r.rows[0];
    set('psYrYou', fmt(f.regular)); set('psYrCatch', fmt(f.catchUp)); set('psYrMatch', fmt(f.match));
    set('psYrShare', fmt(f.share)); set('psYrCounted', fmt(f.regular + f.match + f.share));
    set('psYrRoom', p.applyLimits ? fmt(f.room) : 'Limits not applied');
    var body = document.getElementById('psSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, fmt(row.salary), fmt(row.you), fmt(row.match), fmt(row.share), fmt(row.balance)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('psForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
